import numpy as np
cos = lambda u, v: u @ v / (np.linalg.norm(u) * np.linalg.norm(v))
onehot = {"soft": [1, 0, 0], "teddy bear": [0, 1, 0], "book": [0, 0, 1]}
learned = {"soft": [0.95, 0.32, 0.01], "teddy bear": [0.90, 0.43, 0.05], "book": [0.02, 0.05, 0.99]}
for name, E in [("one-hot", onehot), ("learned", learned)]:
    E = {k: np.array(v, float) for k, v in E.items()}
    print(f"{name:8s} cos(teddy bear, soft)={cos(E['teddy bear'], E['soft']):.3f}"
          f"  cos(teddy bear, book)={cos(E['teddy bear'], E['book']):.3f}")
u = np.array(learned["soft"]); print("2배로 늘려도 cos 는 그대로:", round(cos(2 * u, u), 3), " 내적은", round(2*u@u, 3), "vs", round(u@u, 3))
